// Typed access to data/html.json, generated by tools/extract/html.ts from a
// pinned whatwg/html commit (spec §3.4).

import raw from '../../data/html.json' with { type: 'json' };

export interface ElementRow {
  description: string;
  categories: string[];
  parents: string[];
  children: string[];
  attributes: string[];
  interface: string;
}

export interface Definition {
  url: string;
  categories: string[];
  contexts: string[];
  contentModel: string[];
  attributes: string[];
  tagOmission: string[];
}

export interface AttributeRow {
  name: string;
  /** Element names, or `*` for global attributes. */
  elements: string[];
  on: string;
  description: string;
  /** The value column of the attribute index, verbatim. */
  value: string;
  keywords: string[];
  /** True when the value is one of `keywords` (or empty, when `emptyAllowed`). */
  closed: boolean;
  emptyAllowed: boolean;
}

export interface LinkType {
  keyword: string;
  /** Effect on link, on a and area, and on form; null where the keyword isn't allowed. */
  link: string | null;
  aArea: string | null;
  form: string | null;
  bodyOk: boolean;
}

export interface HtmlData {
  source: { repo: string; commit: string; date: string; file: string; sha256: string };
  elements: Record<string, ElementRow>;
  definitions: Record<string, Definition>;
  categories: Record<string, { elements: string[]; conditional: { element: string; condition: string }[] }>;
  attributes: AttributeRow[];
  autofill: { modes: string[]; fields: string[]; contactTypes: string[]; contactFields: string[] };
  eventHandlers: { name: string; on: string }[];
  inputAttributes: Record<string, string[]>;
  inputTypes: { keyword: string; state: string }[];
  linkTypes: LinkType[];
  obsoleteElements: { element: string; advice: string }[];
  obsoleteAttributes: { attribute: string; elements: string[]; advice: string }[];
}

export const HTML: HtmlData = raw;

export const SPEC = `whatwg/html@${HTML.source.commit.slice(0, 7)}`;

export const HTML_ELEMENTS: ReadonlySet<string> = new Set(Object.keys(HTML.elements));

/** Section URL of an element's definition. */
export function elementUrl(name: string): string | null {
  return HTML.definitions[name]?.url ?? null;
}

const GLOBAL = '*';

/** Attribute rows by attribute name, then element (`*` for global). */
const ROWS = new Map<string, Map<string, AttributeRow>>();
for (const row of HTML.attributes) {
  const byElement = ROWS.get(row.name) ?? new Map<string, AttributeRow>();
  for (const element of row.elements) byElement.set(element, row);
  ROWS.set(row.name, byElement);
}

/**
 * The attribute index row that defines `attribute` on `element`, element-specific
 * first. The element index sometimes lists an attribute the attribute index
 * gives only for other elements (form's rel); those borrow that row.
 */
export function attributeRow(element: string, attribute: string): AttributeRow | null {
  const byElement = ROWS.get(attribute);
  const row = byElement?.get(element) ?? byElement?.get(GLOBAL);
  if (row) return row;
  if (byElement && HTML.elements[element]?.attributes.includes(attribute)) return byElement.values().next().value ?? null;
  return null;
}

const HANDLERS = new Map(HTML.eventHandlers.map((h) => [h.name, h.on]));

/** Event handler content attributes allowed on `element`. */
export function isEventHandler(element: string, attribute: string): boolean {
  const on = HANDLERS.get(attribute);
  if (on === undefined) return false;
  return /HTML elements/.test(on) || on.split(/[;,]\s*/).includes(element);
}

export function isBooleanRow(row: AttributeRow | null): boolean {
  return row?.value === 'Boolean attribute';
}

/** The spec's advice, cut to its first sentence when it runs long. */
function brief(advice: string): string {
  return advice.length <= 200 ? advice : (advice.split(/(?<=\.)\s/)[0] ?? advice);
}

const OBSOLETE_ELEMENTS = new Map(HTML.obsoleteElements.map((o) => [o.element, brief(o.advice)]));

export function obsoleteElement(name: string): string | null {
  return OBSOLETE_ELEMENTS.get(name) ?? null;
}

const OBSOLETE_ATTRIBUTES = new Map<string, string>();
for (const o of HTML.obsoleteAttributes) {
  for (const element of o.elements.length ? o.elements : [GLOBAL]) {
    const key = `${element} ${o.attribute}`;
    if (!OBSOLETE_ATTRIBUTES.has(key)) OBSOLETE_ATTRIBUTES.set(key, brief(o.advice));
  }
}

/** The spec's advice when `attribute` is obsolete on `element`, or null. */
export function obsoleteAttribute(element: string, attribute: string): string | null {
  return OBSOLETE_ATTRIBUTES.get(`${element} ${attribute}`) ?? OBSOLETE_ATTRIBUTES.get(`${GLOBAL} ${attribute}`) ?? null;
}

export const INPUT_TYPES: ReadonlySet<string> = new Set(HTML.inputTypes.map((t) => t.keyword));

/** Input types an input-specific attribute applies to; null when it applies to every type. */
export function inputTypesFor(attribute: string): readonly string[] | null {
  return HTML.inputAttributes[attribute] ?? null;
}

export const LINK_TYPES: ReadonlyMap<string, LinkType> = new Map(HTML.linkTypes.map((l) => [l.keyword, l]));
